package java_practice;

public class ASCII {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char var1='A';
		char var2='a';
		char var3='0';
		char var4='@';
		
		System.out.println("ASCII Value of A = " + (int)var1);
		System.out.println("ASCII Value of a = " + (int)var2);
		System.out.println("ASCII Value of 0 = " + (int)var3);
		System.out.println("ASCII Value of @ = " + (int)var4);
		
		
		char alpha1='A';
		int value1=alpha1;
		
		char alpha2='a';
		int value2=alpha2;
		
		char alpha3='0';
		int value3=alpha3;
		
		char alpha4='@';
		int value4=alpha4;
		
		System.out.println("ASCII Value of A:"+ value1);
		System.out.println("ASCII Value of a:"+ value2);
		System.out.println("ASCII Value of 0:"+ value3);
		System.out.println("ASCII Value of @ :"+ value4);
		
		
		char x='A';
		char y='a';
		char z='0';
		char w='@';
		
		
		System.out.println("ASCII Value of A = " +(int)x);
		System.out.println("ASCII Value of a = " +(int)y);
		System.out.println("ASCII Value of 0 = " +(int)z);
		System.out.println("ASCII Value of @ = " +(int)w);
		
		
		
		double d=10.89;
		int a=(int)d;
		System.out.println(a);
				

	}

}
